[ idryomov: rename err_out_device_del -> err_out_device ]

Cc: stable@vger.kernel.org
Fixes: 27c97abc30e2 ("rbd: add add_disk() error handling")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Dawei Feng <dawei.feng@seu.edu.cn>
Reviewed-by: Ilya Dryomov <idryomov@gmail.com>
Signed-off-by: Ilya Dryomov <idryomov@gmail.com>

Here is the root cause:
do_rbd_add() calls device_add() before device_add_disk(). If device_add_disk() fails, the error path directly calls rbd_free_disk() and then later falls through to rbd_dev_device_release(), which calls rbd_free_disk() again. This double teardown leaves blk-mq cleanup operating on invalid state, causing a null-ptr-deref in __blk_mq_free_map_and_rqs().

Here is the patch:

 static ssize_t do_rbd_add(const char *buf, size_t count)
 {
 	struct rbd_device *rbd_dev = NULL;
 	struct ceph_options *ceph_opts = NULL;
 	struct rbd_options *rbd_opts = NULL;
 	struct rbd_spec *spec = NULL;
 	struct rbd_client *rbdc;
 	int rc;

 	if (!capable(CAP_SYS_ADMIN))
 		return -EPERM;

 	if (!try_module_get(THIS_MODULE))
 		return -ENODEV;

 	/* parse add command */
 	rc = rbd_add_parse_args(buf, &ceph_opts, &rbd_opts, &spec);
 	if (rc < 0)
 		goto out;

 	rbdc = rbd_get_client(ceph_opts);
 	if (IS_ERR(rbdc)) {
 		rc = PTR_ERR(rbdc);
 		goto err_out_args;
 	}

 	/* pick the pool */
 	rc = ceph_pg_poolid_by_name(rbdc->client->osdc.osdmap, spec->pool_name);
 	if (rc < 0) {
 		if (rc == -ENOENT)
 			pr_info("pool %s does not exist\n", spec->pool_name);
 		goto err_out_client;
 	}
 	spec->pool_id = (u64)rc;

 	rbd_dev = rbd_dev_create(rbdc, spec, rbd_opts);
 	if (!rbd_dev) {
 		rc = -ENOMEM;
 		goto err_out_client;
 	}
 	rbdc = NULL;		/* rbd_dev now owns this */
 	spec = NULL;		/* rbd_dev now owns this */
 	rbd_opts = NULL;	/* rbd_dev now owns this */

 	/* if we are mapping a snapshot it will be a read-only mapping */
 	if (rbd_dev->opts->read_only ||
 	    strcmp(rbd_dev->spec->snap_name, RBD_SNAP_HEAD_NAME))
 		__set_bit(RBD_DEV_FLAG_READONLY, &rbd_dev->flags);

 	rbd_dev->config_info = kstrdup(buf, GFP_KERNEL);
 	if (!rbd_dev->config_info) {
 		rc = -ENOMEM;
 		goto err_out_rbd_dev;
 	}

 	rc = rbd_dev_image_probe(rbd_dev, 0);
 	if (rc < 0)
 		goto err_out_rbd_dev;

 	if (rbd_dev->opts->alloc_size > rbd_dev->layout.object_size) {
 		rbd_warn(rbd_dev, "alloc_size adjusted to %u",
 			 rbd_dev->layout.object_size);
 		rbd_dev->opts->alloc_size = rbd_dev->layout.object_size;
 	}

 	rc = rbd_dev_device_setup(rbd_dev);
 	if (rc)
 		goto err_out_image_probe;

 	rc = rbd_add_acquire_lock(rbd_dev);
 	if (rc)
 		goto err_out_image_lock;

 	/* Everything's ready.  Announce the disk to the world. */

 	rc = device_add(&rbd_dev->dev);
 	if (rc)
 		goto err_out_image_lock;

 	rc = device_add_disk(&rbd_dev->dev, rbd_dev->disk, NULL);
 	if (rc)
-		goto err_out_cleanup_disk;
+		goto err_out_device;

 	spin_lock(&rbd_dev_list_lock);
 	list_add_tail(&rbd_dev->node, &rbd_dev_list);
 	spin_unlock(&rbd_dev_list_lock);

 	pr_info("%s: capacity %llu features 0x%llx\n", rbd_dev->disk->disk_name,
 		(unsigned long long)get_capacity(rbd_dev->disk) << SECTOR_SHIFT,
 		rbd_dev->header.features);
 	rc = count;
 out:
 	module_put(THIS_MODULE);
 	return rc;

-err_out_cleanup_disk:
-	rbd_free_disk(rbd_dev);
+err_out_device:
+	device_del(&rbd_dev->dev);
 err_out_image_lock:
 	rbd_dev_image_unlock(rbd_dev);
 	rbd_dev_device_release(rbd_dev);
 err_out_image_probe:
 	rbd_dev_image_release(rbd_dev);
 err_out_rbd_dev:
 	rbd_dev_destroy(rbd_dev);
 err_out_client:
 	rbd_put_client(rbdc);
 err_out_args:
 	rbd_spec_put(spec);
 	kfree(rbd_opts);
 	goto out;
 }



